<script setup>
import { reactive, watch } from 'vue'; import MButton from '../../../components/mds/MButton.vue'; import MInput from '../../../components/mds/MInput.vue'; import MMobileTopBar from '../../../components/mds/MMobileTopBar.vue'; import MSelect from '../../../components/mds/MSelect.vue'; import MTextarea from '../../../components/mds/MTextarea.vue'; import { toMonitoringQueryDraft,toMonitoringQueryPayload } from '../domain/monitoring-query-write.mjs';
const props=defineProps({record:Object,editing:Boolean,saving:Boolean,error:String,safeAreaStyle:Object});const emit=defineEmits(['cancel','save']);const draft=reactive({...toMonitoringQueryDraft()});watch(()=>props.record,(record)=>Object.assign(draft,toMonitoringQueryDraft(record)),{immediate:true});const categories=[{value:'brand',label:'Thương hiệu'},{value:'industry',label:'Ngành'},{value:'competitor',label:'Đối thủ'}];const types=[{value:'news',label:'Báo chí'},{value:'social',label:'Mạng xã hội'},{value:'web',label:'Web'}];const states=[{value:true,label:'Bật'},{value:false,label:'Tắt'}];function submit(){emit('save',toMonitoringQueryPayload(draft));}
</script>
<template><section class="mds-mobile-app flex h-[100dvh] min-w-0 flex-col overflow-hidden bg-[var(--mds-bg)]" :style="safeAreaStyle"><MMobileTopBar :title="editing?'Sửa bộ từ khóa':'Thêm bộ từ khóa'" @back="emit('cancel')"/><form class="min-h-0 flex flex-1 flex-col" @submit.prevent="submit"><main class="min-h-0 flex-1 overflow-y-auto"><div class="mds-mobile-gutter-x space-y-4 py-4"><p v-if="error" class="rounded-lg bg-[var(--mds-danger-bg)] px-3 py-2 text-[13px] text-[var(--mds-danger)]">{{error}}</p><p class="rounded-lg bg-[var(--mds-bg-page)] px-3 py-2 text-[13px]">Lưu cấu hình không tự chạy quét.</p><label><span class="mb-1 block text-[13px] font-medium">Tên bộ từ khóa</span><MInput v-model="draft.name" placeholder="Theo dõi thương hiệu MISA"/></label><label><span class="mb-1 block text-[13px] font-medium">Phân loại</span><MSelect v-model="draft.category" :options="categories"/></label><label><span class="mb-1 block text-[13px] font-medium">Nguồn quét</span><MSelect v-model="draft.queryType" :options="types"/></label><label><span class="mb-1 block text-[13px] font-medium">Từ khóa bao gồm</span><MTextarea v-model="draft.include" :rows="3" placeholder="MISA, AMIS"/></label><label><span class="mb-1 block text-[13px] font-medium">Từ khóa loại trừ</span><MTextarea v-model="draft.exclude" :rows="3" placeholder="Không liên quan"/></label><label><span class="mb-1 block text-[13px] font-medium">Trạng thái</span><MSelect v-model="draft.enabled" :options="states"/></label></div></main><footer class="flex gap-2 border-t border-[var(--mds-border-light)] bg-[var(--mds-bg)] px-4 pb-[calc(12px+var(--mds-mobile-safe-bottom))] pt-3"><MButton variant="neutral" class="flex-1 [&]:h-[var(--mds-mobile-touch-target)]" :disabled="saving" @click="emit('cancel')">Hủy</MButton><MButton variant="primary" class="flex-1 [&]:h-[var(--mds-mobile-touch-target)]" :loading="saving" @click="submit">{{editing?'Lưu':'Thêm'}}</MButton></footer></form></section></template>
